import AVFoundation
import Foundation

/// Plays Velora's synthesized UI sounds (design brief §5): rising = listening,
/// a tick = released, falling = done, low pair = nothing was heard, single
/// low tone = error. Assets are generated by scripts/make-sounds.sh into
/// Resources/ and bundled into the .app.
final class SoundPlayer {
    /// `rawValue` is the asset name, so a case and its .caf must be renamed
    /// together. Asset names are per-sound-set: Classic is bare, Soft and
    /// Chime prefix the set (`soft-prestop`).
    enum Cue: String, CaseIterable {
        case start, stop, error
        /// Fires the instant the key is released, before any transcript
        /// exists, so the ear gets an answer at 0 ms. Shorter and quieter
        /// than `stop`, which means "the result is here".
        case preStop = "prestop"
        /// A take that ended with nothing above the speech floor. Not an
        /// error: no text was produced, so it gets its own sound.
        case noResult = "noresult"
    }

    private var players: [Cue: AVAudioPlayer] = [:]
    private let cues: [Cue]
    private var loadedSet: SoundSet?

    /// Loads `cues`; a player that loads none stays silent (selftest).
    init(cues: [Cue] = Cue.allCases) {
        self.cues = cues
        // The selftest's empty initializer must not resolve app preferences
        // or load a device-backed player.
        if !cues.isEmpty { load(AppConfig.shared.soundSet) }
    }

    private func load(_ set: SoundSet) {
        guard loadedSet != set else { return }
        players.values.forEach { $0.stop() }
        players.removeAll()
        loadedSet = set
        for cue in cues {
            let name = set.assetName(for: cue.rawValue)
            guard let url = ResourceLocator.resource(named: name, extension: "caf") else {
                NSLog("Velora: missing sound asset %@.caf (run scripts/make-sounds.sh)", cue.rawValue)
                continue
            }
            do {
                let player = try AVAudioPlayer(contentsOf: url)
                player.prepareToPlay()
                players[cue] = player
            } catch {
                NSLog("Velora: failed to load %@.caf: %@", cue.rawValue, "\(error)")
            }
        }
    }

    /// Plays a cue if sounds are enabled; volume from the settings slider.
    func play(_ cue: Cue, preview: Bool = false) {
        guard !cues.isEmpty else { return }
        let config = AppConfig.shared
        guard preview || config.soundsEnabled else { return }
        load(config.soundSet)
        guard let player = players[cue] else { return }
        player.volume = Float(config.soundVolume / 100.0)
        player.currentTime = 0
        player.play()
    }
}
